insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('elf-bar-10000-puffs', 'Elf Bar 10000 Puffs Digital Display — Blue Razz Ice', 'Elf Bar', 'Disposable Vape', 40.00, 55.00, '10,000 Puffs', '50mg (5%)', 'Chilled Blue Raspberry', '/images/product_elfbar_10k_1794713684201.jpg', 48, true, true, 'Engineered with Quaq mesh coil technology and a real-time digital telemetry display tracking battery percentage and e-liquid levels. ESMA UAE compliant.', '["Chilled Blue Raspberry","Watermelon Bubblegum Ice","Peach Mango Guava","Blackberry Cranberry Mint"]'::jsonb, '["50mg (5%)","20mg (2%)"]'::jsonb, '{"battery":"850mAh USB-C Fast Charge","capacity":"18ml Pre-filled Mesh Coil","display":"Live E-Liquid & Battery OLED"}'::jsonb, '{"gallery":["/images/product_elfbar_10k_1794713684201.jpg","/images/hero_vape_display_1794713683463.jpg","/images/product_podsalt_35k_1794713685262.jpg"],"longDescription":["The Elf Bar 10000 Puffs Digital Display edition represents the next generation of high-capacity disposable hardware tailored for adult vapers across Dubai and the UAE. Built around an anodized aluminum-polycarbonate chassis, it integrates a high-contrast side OLED screen that eliminates dry hits by displaying exact battery percentage and remaining e-liquid saturation in real time.","Powered by Elf Bar’s proprietary QUAQ ultra-fine mesh heating element, every draw atomizes at a calibrated temperature curve to preserve crisp fruit notes from the first puff to the 10,000th. The 850mAh high-density cobalt cell recharges from 0% to 80% in just 28 minutes via the bottom USB-C port, ensuring uninterrupted all-day reliability."],"highlights":["Real-time OLED digital telemetry for live battery % and e-liquid level monitoring","QUAQ 1.0Ω precision mesh coil engineered for zero flavor degradation across 18ml capacity","Anti-leak multi-layer silicone chamber seal tested for high UAE summer temperatures","Official ESMA UAE compliant stock with verifiable QR hologram authenticity code"],"tastingNotes":{"inhale":"Tangy candied blue raspberry burst with bright berry aromatics","body":"Balanced sweet-tart berry compote with smooth nicotine salt throat hit","finish":"Crisp arctic menthol exhale that leaves a clean, refreshing palate","iceLevel":"4 / 5 — High Cooling Frost","sweetnessLevel":"3.5 / 5 — Balanced Sweet Berry"},"boxContents":["1× Elf Bar 10000 Puffs Digital Display Disposable Device (18ml Pre-filled)","1× Hygienic Silicone Mouthpiece Seal & Airflow Sticker","1× Official UAE Excise Tax Stamp & Scratch-Off QR Verification Box","1× Multilingual User Safety & ESMA Compliance Guide"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('pod-salt-35k-puffs', 'Pod Salt 35K Puffs Smart Screen — Double Apple Shisha', 'Pod Salt', 'Disposable Vape', 65.00, 80.00, '35,000 Puffs', '20mg (2%)', 'Authentic Two Apple Molasses', '/images/product_podsalt_35k_1794713685262.jpg', 48, true, true, 'Flagship ultra-high capacity disposable hardware featuring switchable Eco (35K) and Boost (20K) wattage modes with British-formulated nicotine salts.', '["Authentic Two Apple Molasses","Blue Mist Berry Ice","Cuban Creme Tobacco","Fresh Mint Leaf Freeze"]'::jsonb, '["20mg (2%)","50mg (5%)"]'::jsonb, '{"battery":"1000mAh Dual Mode Boost","capacity":"28ml Dual Mesh Tank","display":"Curved Smart HD Display"}'::jsonb, '{"gallery":["/images/product_podsalt_35k_1794713685262.jpg","/images/hero_vape_display_1794713683463.jpg","/images/product_elfbar_10k_1794713684201.jpg"],"longDescription":["Designed in the United Kingdom and filled with Pod Salt’s award-winning salicylic nicotine salt formula, the Pod Salt 35K Smart Screen is our highest-capacity flagship disposable in Dubai. Its wrap-around curved HD display provides instant visual telemetry for wattage output, puff counter, battery reserve, and dual-tank e-liquid volume.","Switch effortlessly between Eco Mode (alternating single-mesh firing for up to 35,000 puffs) and Boost Mode (simultaneous dual-mesh 24W firing for 20,000 dense, shisha-grade clouds). The Double Apple Shisha blend replicates traditional Old Dubai lounge molasses with red sweet apples, crisp green apples, and a subtle aniseed undertone."],"highlights":["Switchable Eco Mode (35,000 Puffs) and Dual-Mesh Boost Mode (20,000 Puffs)","Formulated in the UK with pharmaceutical-grade nicotine salts for ultra-smooth throat hit","Curved 3D Smart HD Display with live puff counter and wattage animation","Stepless bottom airflow slider from tight MTL draw to restricted direct-lung (RDL)"],"tastingNotes":{"inhale":"Rich caramelized red apple and crisp granny smith apple","body":"Authentic Middle Eastern shisha molasses with warm spice nuances","finish":"Smooth, lingering aniseed and gentle cooling exhale","iceLevel":"2.5 / 5 — Gentle Lounge Coolness","sweetnessLevel":"4 / 5 — Rich Molasses Sweetness"},"boxContents":["1× Pod Salt 35K Puffs Dual-Boost Smart Disposable Device (28ml)","1× Pre-installed Ergonomic Soft-Touch Drip Tip Cover","1× UK Batch Authenticity Hologram & UAE Tax Stamp Seal","1× Quick-Start Wattage & Airflow Adjustment Card"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('juul-2-starter-kit', 'Juul 2 Starter Kit — Slate Grey Device + 2 Virginia & Menthol Pods', 'JUUL', 'Pods System', 135.00, null, 'Closed Pod Kit', '18mg/ml', 'Virginia Tobacco & Crisp Menthol', '/images/product_juul2_kit_1794713684954.jpg', 48, true, false, 'Official UAE JUUL2 Starter Kit complete with Slate Grey device, USB magnetic charging dock, and two authentic 18mg/ml JUUL2 pods with smart pod ID recognition.', '["Virginia Tobacco & Crisp Menthol","Autumn Tobacco & Polar Menthol","Ruby Menthol Berry Pack","Summer Menthol Tropical Pack"]'::jsonb, '["18mg/ml Official UAE Spec"]'::jsonb, '{"battery":"25% Larger Smart Battery + Dock","capacity":"2x 1.2ml Authentic JUUL2 Pods","display":"4-LED Smart Pulse Interface"}'::jsonb, '{"gallery":["/images/product_juul2_kit_1794713684954.jpg","/images/hero_vape_display_1794713683463.jpg","/images/product_elfbar_10k_1794713684201.jpg"],"longDescription":["The official UAE JUUL2 Starter Kit is engineered for adult smokers seeking a clean, dependable, and pocket-friendly transition from combustible cigarettes. Featuring a 25% larger battery capacity and 70% more e-liquid per pod compared to the original generation, the Slate Grey weather-resistant aluminum chassis delivers consistent temperature-regulated vapor from full charge to empty.","Each authentic JUUL2 pod contains an encrypted cryptographic microchip that communicates directly with the device upon magnetic insertion—automatically verifying pod authenticity to prevent counterfeit pods and calibrating the exact heating profile for Virginia Tobacco or Crisp Menthol."],"highlights":["Cryptographic Smart Pod-ID chip blocks counterfeit pods and auto-calibrates temperature","4-LED smart light interface communicates battery charge level and remaining e-liquid","Sealed metallic wick heating system engineered for zero spitting or pocket leakage","Includes magnetic high-speed USB charging dock (full charge in under 30 minutes)"],"tastingNotes":{"inhale":"Clean, oven-cured American Virginia brightleaf tobacco","body":"Authentic toasted leaf warmth paired with a separate Crisp Peppermint Menthol pod","finish":"Dry, cigarette-style throat hit with zero lingering sweetness","iceLevel":"3 / 5 — Crisp Peppermint (Menthol Pod)","sweetnessLevel":"1 / 5 — Authentic Unsweetened Leaf"},"boxContents":["1× Rechargeable JUUL2 Device in Anodized Slate Grey","1× Authentic JUUL2 Virginia Tobacco Pod (1.2ml, 18mg/ml)","1× Authentic JUUL2 Crisp Menthol Pod (1.2ml, 18mg/ml)","1× Magnetic USB Charging Dock & Official UAE Warranty Booklet"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('vozol-star-20000-puffs', 'Vozol Star 20000 Puffs Mirror Screen — Lush Watermelon Ice', 'Vozol', 'Disposable Vape', 50.00, 65.00, '20,000 Puffs', '50mg (5%)', 'Sweet Red Watermelon & Ice', '/images/product_elfbar_10k_1794713684201.jpg', 48, true, true, 'Features a full-surface mirror screen that illuminates on draw with dual-power Eco/Power switch and hygienic mouthpiece protection cap.', '["Sweet Red Watermelon & Ice","Grape Ice Freeze","Miami Mint Citrus","Dragon Strawnana"]'::jsonb, '["50mg (5%)","20mg (2%)"]'::jsonb, '{"battery":"650mAh Rapid USB-C","capacity":"24ml Dual Mesh S.i.L.C Tech","display":"2.2-Inch HD Mirror LED Screen"}'::jsonb, '{"gallery":["/images/product_elfbar_10k_1794713684201.jpg","/images/product_podsalt_35k_1794713685262.jpg","/images/hero_vape_display_1794713683463.jpg"],"longDescription":["The Vozol Star 20000 Puffs combines avant-garde industrial styling with Vozol’s patented S.i.L.C. (Smooth, Identical, Long-lasting, Clean) dual-mesh atomization platform. When idle, the front panel presents a sleek electroplated mirror finish; upon drawing or pressing the mode button, a vibrant 2.2-inch color matrix display lights up through the mirror.","Designed specifically for outdoor lifestyles in the Emirates, it includes a snap-on magnetic mouthpiece dust cap that keeps sand and pocket lint out of the airway. Toggle between Eco Mode (20,000 puffs) and Power Mode (15,000 high-density puffs) with a single click."],"highlights":["2.2-inch hidden electroplated Mirror HD Screen with dynamic wattage telemetry","Dual S.i.L.C. mesh coils prevent carbon buildup and maintain pure fruit clarity","Integrated magnetic mouthpiece hygiene cap ideal for beach and desert carry","Fast Type-C charging reaches 100% battery in 35 minutes"],"tastingNotes":{"inhale":"Juicy sun-ripened red watermelon nectar","body":"Crisp melon rind freshness with vibrant candy undertones","finish":"Sub-zero menthol breeze on the exhale","iceLevel":"4.5 / 5 — Intense Glacial Freeze","sweetnessLevel":"4 / 5 — Juicy Summer Melon"},"boxContents":["1× Vozol Star 20000 Puffs Mirror Screen Device (24ml)","1× Attached Magnetic Hygienic Mouthpiece Cap","1× ESMA UAE Authenticity Sticker & User Manual"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('pod-salt-nic-salt-30ml', 'Pod Salt Reserve 30ml Nicotine Salt — Cuban Creme Tobacco', 'Pod Salt', 'E-Liquid', 45.00, null, '30ml Bottle', '25mg / 50mg', 'Aged Havana Leaf & Madagascar Vanilla', '/images/product_eliquid_bottle_1794713685538.jpg', 48, true, false, 'Premium UK-manufactured nicotine salt e-liquid crafted specifically for low-wattage pod systems. Ultra-smooth throat hit with rich aromatic vapor.', '["Aged Havana Leaf & Madagascar Vanilla","Blue Raspberry Slush","Mango Ice Nexus","Virginia Gold Tobacco"]'::jsonb, '["20mg (2.0%)","36mg (3.6%)","50mg (5.0%)"]'::jsonb, '{"battery":"50/50 VG/PG Ratio for Pods","capacity":"30ml Chubby Gorilla Unicorn","display":"ESMA Excise Tax Stamp Sealed"}'::jsonb, '{"gallery":["/images/product_eliquid_bottle_1794713685538.jpg","/images/product_podsalt_35k_1794713685262.jpg","/images/hero_vape_display_1794713683463.jpg"],"longDescription":["Part of Pod Salt’s prestigious Origin Reserve collection crafted in the UK, Cuban Creme Tobacco is blended to a balanced 50% VG / 50% PG viscosity ratio. This ensures rapid wicking and extended coil life in all refillable MTL pod systems such as the Vaporesso XROS 4 Pro and Uwell Caliburn G3.","Unlike standard freebase e-liquids that become harsh at higher strengths, Pod Salt’s refined nicotine salt formulation neutralizes pH alkalinity—delivering immediate nicotine satisfaction with a velvety throat hit."],"highlights":["Balanced 50VG/50PG ratio engineered for 0.6Ω to 1.2Ω refillable pod cartridges","Manufactured in ISO-7 cleanrooms in the United Kingdom","Child-resistant tamper-evident 30ml precision dropper bottle","Sealed with official UAE Federal Tax Authority digital excise stamp"],"tastingNotes":{"inhale":"Earthy, hand-rolled Havana cigar leaf with woody cedar notes","body":"Whipped Madagascar vanilla bean custard and caramelized brown sugar","finish":"Warm, velvety tobacco reserve finish with zero harshness","iceLevel":"0 / 5 — Pure Non-Menthol Reserve","sweetnessLevel":"2.5 / 5 — Subtle Custard Warmth"},"boxContents":["1× 30ml Pod Salt Reserve Nicotine Salt E-Liquid Bottle","1× Child-Proof Precision Needle-Tip Filling Cap","1× UAE Excise Tax Sealed Outer Carton & Safety Leaflet"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('vaporesso-xros-4-pro-kit', 'Vaporesso XROS 4 Pro Vape Kit — Brushed Titanium Alloy', 'Vaporesso', 'Vape Kit', 145.00, 170.00, 'Refillable Kit', '0mg Hardware (Pods Included)', '0.4Ω & 0.8Ω COREX 2.0 Mesh Pods', '/images/product_podsalt_35k_1794713685262.jpg', 48, true, true, 'Aerospace-grade aluminum unibody pod system with precise 0.5W wattage increments, physical slide-lock switch, and COREX 2.0 morph-mesh heating pods.', '["Brushed Titanium Alloy","Obsidian Matte Black","Champagne Gold Satin","Cobalt Blue Anodized"]'::jsonb, '["0.4Ω + 0.8Ω COREX 2.0 Mesh","0.6Ω + 1.0Ω COREX 2.0 Mesh"]'::jsonb, '{"battery":"1200mAh 2A SuperCharge (35 Min)","capacity":"3.0ml Clamshell Top-Fill Pods","display":"AXON Chipset + TFT Wattage Screen"}'::jsonb, '{"gallery":["/images/product_podsalt_35k_1794713685262.jpg","/images/hero_vape_display_1794713683463.jpg","/images/product_juul2_kit_1794713684954.jpg"],"longDescription":["The Vaporesso XROS 4 Pro is the pinnacle of refillable pod engineering. CNC-machined from 7-stage stretched aerospace aluminum alloy, it houses a high-capacity 1200mAh battery capable of full 2A rapid charging in just 35 minutes. The vivid TFT screen displays exact wattage (adjustable in 0.5W steps when using the 0.4Ω pod) or three intelligent output modes (Eco, Normal, Pulse).","Equipped with Vaporesso’s upgraded COREX 2.0 morph-mesh pods and cumulus microfiber cotton, it boosts aroma reproduction by 30% and extends pod lifespan by 30%. A dedicated physical slide-lock switch on the side prevents accidental pocket firing."],"highlights":["COREX 2.0 Morph-Mesh technology increases flavor accuracy and pod longevity by 30%","Physical side slide-lock button locks fire button while keeping auto-draw active","1200mAh high-density battery with 2A USB-C SuperCharge (100% in 35 minutes)","Fully compatible with the entire XROS pod family (0.4Ω, 0.6Ω, 0.8Ω, 1.0Ω, 1.2Ω)"],"tastingNotes":{"inhale":"Instant 0.01s AXON pulse ignition for immediate warm vapor","body":"Precision airflow slider transitions from tight cigarette MTL to open RDL","finish":"Ultra-clean flavor separation for both 50/50 nic salts and 70/30 freebase","iceLevel":"Hardware Kit — Customizable by E-Liquid","sweetnessLevel":"COREX 2.0 High-Fidelity Flavor Reproduction"},"boxContents":["1× Vaporesso XROS 4 Pro Battery Body (1200mAh)","1× XROS Series 0.4Ω MESH Pod (3ml Top-Fill, Pre-installed)","1× XROS Series 0.8Ω MESH Pod (3ml Top-Fill, In Box)","1× Braided Type-C Charging Cable, Reminder Card & Warranty Manual"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('tugboat-super-12000-puffs', 'Tugboat Super 12000 Puffs Digital — Mango Passionfruit Freeze', 'Tugboat', 'Disposable Vape', 38.00, null, '12,000 Puffs', '50mg (5%)', 'Alphonso Mango & Passionfruit Ice', '/images/product_elfbar_10k_1794713684201.jpg', 48, true, false, 'UAE best-selling tropical disposable delivering intense exotic fruit notes paired with a sub-zero menthol finish and adjustable bottom airflow.', '["Alphonso Mango & Passionfruit Ice","Lush Watermelon Bubblegum","Purple Rain Berry Mix","Gummy Bear Ice"]'::jsonb, '["50mg (5%)","20mg (2%)"]'::jsonb, '{"battery":"600mAh Type-C Rechargeable","capacity":"14ml Dual Mesh Coil","display":"Bottom Digital Status Ring"}'::jsonb, '{"gallery":["/images/product_elfbar_10k_1794713684201.jpg","/images/hero_vape_display_1794713683463.jpg","/images/product_podsalt_35k_1794713685262.jpg"],"longDescription":["A longtime favorite across Dubai and Sharjah, the Tugboat Super 12000 Digital upgrades the classic Tugboat silhouette with a dual-mesh 1.0Ω coil core and a bottom digital telemetry ring. It delivers an unmistakable, punchy throat hit alongside vibrant tropical fruit saturation.","The ergonomic matte-rubberized body resists fingerprints and heat while providing rotary airflow control at the base, allowing you to fine-tune draw resistance on the go."],"highlights":["Dual-mesh 1.0Ω heating core for dense, saturated tropical fruit clouds","Soft-touch rubberized grip finish with rotary bottom airflow control ring","Compact pocket dimensions holding 14ml of 50mg/ml nicotine salt e-liquid","Digital battery and e-liquid status indicators integrated at the base"],"tastingNotes":{"inhale":"Ripe Indian Alphonso mango nectar","body":"Zesty tropical passionfruit pulp with tangy citrus highlights","finish":"Crisp glacier ice finish that balances the tropical sweetness","iceLevel":"4 / 5 — Chilled Tropical Frost","sweetnessLevel":"4.5 / 5 — Rich Exotic Nectar"},"boxContents":["1× Tugboat Super 12000 Puffs Digital Disposable Device (14ml)","1× Sealed Foil Freshness Pouch & Silicone Stopper","1× Authentic Tugboat Hologram Security Code Box"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('vgod-cubano-black-saltnic', 'VGOD SaltNic Labs 30ml E-Liquid — Cubano Black Reserve', 'VGOD', 'E-Liquid', 55.00, null, '30ml Bottle', '25mg / 50mg', 'Bold Cigar Leaf & Rich Vanilla Custard', '/images/product_eliquid_bottle_1794713685538.jpg', 48, true, false, 'Aged robust Cuban tobacco notes layered with rich, creamy vanilla custard. Sealed with verifiable hologram authenticity code.', '["Bold Cigar Leaf & Rich Vanilla Custard","Cubano Silver Honey","Lush Ice Watermelon Menthol","Purple Bomb Grape Ice"]'::jsonb, '["25mg (2.5%)","50mg (5.0%)"]'::jsonb, '{"battery":"Optimized for Refillable Pods","capacity":"30ml Sealed Authenticity Bottle","display":"Official UAE Tax Stamp Verified"}'::jsonb, '{"gallery":["/images/product_eliquid_bottle_1794713685538.jpg","/images/hero_vape_display_1794713683463.jpg","/images/product_podsalt_35k_1794713685262.jpg"],"longDescription":["VGOD’s Cubano Black from SaltNic Labs in California is widely regarded as the gold standard of dessert-tobacco salt nicotine blends in the Middle East. Aged in oak-style aromatic vats before bottling, it intensifies the dark, smoky character of VGOD’s original Cubano profile.","On the exhale, a rich, velvety layer of whipped vanilla custard rounds out the bold cigar leaf, making it an ideal all-day vape for open pod systems operating between 10W and 18W."],"highlights":["Authentic California-formulated VGOD SaltNic Labs 30ml reserve bottle","Crafted specifically for low-wattage refillable pod devices (10W – 18W)","Zero coil-gunking artificial sweeteners for extended cartridge life","Verified genuine import with scratch-off VGOD serial code and UAE tax stamp"],"tastingNotes":{"inhale":"Robust, dark-cured Cuban cigar leaf with smoky espresso undertones","body":"Rich, creamy French vanilla custard and warm caramelized sugar","finish":"Smooth, full-bodied cigar lounge aroma on the exhale","iceLevel":"0 / 5 — Warm Aged Tobacco Reserve","sweetnessLevel":"3 / 5 — Rich Vanilla Custard Balance"},"boxContents":["1× 30ml VGOD SaltNic Labs Cubano Black Bottle","1× VGOD Authenticity Hologram & UAE Excise Stamp Carton"]}'::jsonb) on conflict (slug) do nothing;
insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, flavors, nicotine_options, specs, details) values ('uwell-caliburn-g3-pro-kit', 'Uwell Caliburn G3 Pro Full-Screen Kit — Space Grey', 'Uwell', 'Vape Kit', 125.00, null, '35W Pod Kit', '0mg Hardware (2 Pods Included)', 'Pro-FOCS Flavor Technology', '/images/hero_vape_display_1794713683463.jpg', 48, true, false, 'The first full-screen Caliburn system featuring 35W maximum output, auto-draw and button ignition, and crystal-clear e-liquid viewing window.', '["Space Grey Metallic","Midnight Matte Black","Pacific Cobalt Blue","Emerald Green"]'::jsonb, '["0.4Ω + 0.9Ω G3 Pods","0.6Ω + 1.2Ω G3 Pods"]'::jsonb, '{"battery":"1000mAh Integrated High-Density","capacity":"3.0ml ClearView Side-Fill Pod","display":"Full-Panel Dynamic UI Screen"}'::jsonb, '{"gallery":["/images/hero_vape_display_1794713683463.jpg","/images/product_podsalt_35k_1794713685262.jpg","/images/product_juul2_kit_1794713684954.jpg"],"longDescription":["The Uwell Caliburn G3 Pro introduces the first edge-to-edge dynamic full-screen UI in the legendary Caliburn lineup. Cast from solid zinc alloy with a satin Space Grey finish, it pairs a 1000mAh battery with up to 35W of regulated output—unlocking true Restricted Direct Lung (RDL) performance with the included 0.4Ω G3 cartridge.","Uwell’s patented Pro-FOCS flavor restoration technology recycles drawn airflow through the atomizer core to condense aromatic molecules, while ultrasonic-welded G3 pods prevent condensation buildup inside the magnetic bay."],"highlights":["Full-panel dynamic LCD UI displaying wattage, coil resistance, puff count, and battery %","Ultrasonic-welded U² anti-leak cartridge design with oversized ClearView window","Pro-FOCS flavor technology maximizes aroma density for both nic salts and freebase","Dual-way airflow control (reversible pod orientation + precision side airflow slider)"],"tastingNotes":{"inhale":"Instant millisecond auto-draw activation with zero ramp-up delay","body":"Warm, saturated vapor output up to 35W on the 0.4Ω FeCrAl meshed pod","finish":"Crisp, clean flavor fidelity powered by Uwell Pro-FOCS airflow recycling","iceLevel":"Hardware Kit — Customizable by E-Liquid","sweetnessLevel":"Pro-FOCS High-Clarity Aroma Restoration"},"boxContents":["1× Uwell Caliburn G3 Pro Device in Space Grey (1000mAh)","1× 0.4Ω Caliburn G3 Integrated Coil Cartridge (3ml Side-Fill)","1× 0.9Ω Caliburn G3 Integrated Coil Cartridge (2.5ml Side-Fill)","1× USB Type-C Charging Cable & Official User Manual"]}'::jsonb) on conflict (slug) do nothing;
